CREATE TABLE IF NOT EXISTS economy_accounts (id UUID PRIMARY KEY,currency TEXT NOT NULL DEFAULT 'WBX',balance BIGINT NOT NULL DEFAULT 0 CHECK (balance >= 0),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS economy_ledger (id UUID PRIMARY KEY,account_id UUID NOT NULL REFERENCES economy_accounts(id),amount BIGINT NOT NULL CHECK (amount <> 0),balance_after BIGINT NOT NULL CHECK (balance_after >= 0),reason TEXT NOT NULL,reference_id TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_economy_ledger_account_time ON economy_ledger(account_id,created_at DESC);
